# CODE CELL 59 · Deep EDA
fig,(ax,ay)=plt.subplots(2,1,figsize=(12.5,6.5),sharex=True)
v16_axes(fig,[ax,ay]);q,true,wrong=v16_case
for target,axis,title,color in [(true,ax,'Correct structure · cosine ≈ 0.893',VAQUA),(wrong,ay,'Wrong isomer · cosine ≈ 0.952',VCORAL)]:
    qm=np.asarray(q['mz'],dtype=float);tm=np.asarray(target['mz'],dtype=float)
    qv=np.sqrt(np.asarray(q['intensity'],dtype=float))
    tv=np.sqrt(np.asarray(target['intensity'],dtype=float))
    qhit=[np.any(np.abs(tm-z)<=.02) for z in qm]
    thit=[np.any(np.abs(qm-z)<=.02) for z in tm]
    axis.vlines(qm,0,qv,color=[VAQUA if hit else VBLUE for hit in qhit],lw=1.8,alpha=.92,label='query')
    axis.vlines(tm,0,-tv,color=[VGOLD if hit else color for hit in thit],lw=1.8,alpha=.92,label='reference')
    axis.axhline(0,color='#A8BFD3',lw=.8)
    axis.set(ylim=(-1.05,1.05),ylabel='√ intensity')
    axis.set_title(title,loc='left',color=VTXT,fontweight='bold',fontsize=12)
    axis.legend(facecolor=VAX,edgecolor='#3A526A',labelcolor=VTXT,fontsize=9,loc='upper right')
ay.set_xlabel('m/z · tolerance ±0.02 Da')
fig.suptitle('Same acquisition conditions: the wrong isomer wins',x=.045,ha='left',fontsize=16,color=VTXT,fontweight='bold')
fig.tight_layout(rect=[0,0,1,.93]);display(fig);plt.close(fig)
try:
    from rdkit import Chem
    from rdkit.Chem import Draw
    mols=[Chem.MolFromSmiles(true['smiles']),Chem.MolFromSmiles(wrong['smiles'])]
    if all(m is not None for m in mols):
        display(Draw.MolsToGridImage(mols,molsPerRow=2,subImgSize=(410,265),legends=['Correct 2D structure','Similar but incorrect isomer']))
except ImportError:
    from IPython.display import Image
    display(Image(data=base64.b64decode('')))
v16_caption('<b>Measured case.</b> The correct reference gives cosine <b>0.893</b>; a different isomer gives <b>0.952</b>, with the same adduct, instrument and collision energy. Matching peak masses does not guarantee the correct atomic connectivity. This pair calls for more structure-specific evidence, not merely another mass filter.')
